inline constexpr const Recipe* find(std::string_view deviceClass) noexcept {
    for (const auto& recipe : recipes) if (recipe.deviceClass == deviceClass) return &recipe;
    return nullptr;
}
inline constexpr std::string_view identityGyroId(const Recipe& recipe) noexcept {
    return recipe.identityGyroMatrixId.empty() ? recipe.gyroMatrixId : recipe.identityGyroMatrixId;
}
inline constexpr std::string_view identityAccelId(const Recipe& recipe) noexcept {
    return recipe.identityAccelMatrixId.empty() ? recipe.accelMatrixId : recipe.identityAccelMatrixId;
}
